(function(){const RA=globalThis.RA,D=(l,p)=>RA.D(l,p),E=(origin,prefix,root,suffix,source)=>({origin,prefix,root,suffix,source}),C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:"authored"}),M=(errorType,wrong,right,reason)=>({errorType,wrong,right,reason}),Q=(id,senseId,type,prompt,options,answer,explain,errorType)=>({id,senseId,type,prompt,options,answer,explain,errorType});
D("rape",{etymology:E("The sexual-violence noun and verb came through Anglo-French from Latin rapere ‘seize, carry off by force’; the older literary sense ‘plunder’ shares that history. The oilseed plant is a separate word from Old French rape and Latin rapa/rapum ‘turnip’.",null,"rapere",null,"Etymonline, rape (https://www.etymonline.com/word/rape)."),contexts:[C("rape.s1","法律","The training manual defines rape as a serious crime involving sexual activity without consent and explains how to report it safely.","培訓手冊將強姦界定為未經同意的性行為所構成的嚴重犯罪，並說明如何安全通報。","Rape is a serious crime involving sexual activity without consent.","Rape is the object of defines; as a serious crime gives the category, and involving clarifies the legal concept.","The wording centers consent and identifies a criminal offense without graphic detail.") ,C("rape.s2","法律","The court found that the defendant had raped the victim and issued a sentence under the applicable law.","法院認定被告強姦了受害者，並依適用法律判刑。","As a verb, rape means force someone into sexual activity without consent.","Raped takes the person harmed as its object; that-clause states the court's finding.","The sentence uses the verb in its serious criminal sense.") ,C("rape.s3","歷史","The chronicle says the invading army raped the city, meaning that it plundered homes and seized property.","編年史說入侵軍隊洗劫了這座城，意思是掠奪民宅並奪取財物。","In older or literary use, rape can mean violent seizure or plunder of a place or goods.","Raped takes city as its object; the following clause explains the historical sense.","This is the older non-sexual sense of violent plunder.") ,C("rape.s4","植物","The farm planted winter rape for its oil-rich seeds and harvested the yellow-flowering crop the following summer.","農場種植冬油菜以收取富含油分的種子，並在隔年夏天收割開黃花的作物。","Rape is also the name of an oilseed plant, unrelated in origin to the sexual-violence word.","Rape follows planted as the crop; for its oil-rich seeds states the purpose.","The context clearly identifies the agricultural plant sense.")],mistakes:[M("word-choice","The farmer planted rape to harvest edible turnips for the market.","The farmer planted turnips to harvest edible roots for the market.","Rape as a crop is oilseed (such as rapeseed/canola), not the turnip harvested as a root vegetable.")],quiz:[Q("rape.q1","rape.s1","meaning","In a legal training text, rape is identified as ___.",["a serious crime involving sexual activity without consent","an ordinary consensual date","a type of oilseed crop"],"a serious crime involving sexual activity without consent","The source definition centers forced sexual activity without consent.","meaning"),Q("rape.q2","rape.s3","context","An old chronicle says an army “raped the city” and then describes looting homes. Here the verb means ___.",["plundered or violently seized the city","planted an oilseed crop","made a legal ruling"],"plundered or violently seized the city","This is the older literary sense of violent seizure or plunder.","context"),Q("rape.q3","rape.s4","confusable","Which sentence uses rape to name a crop?",["The farm harvested rape for its oil-rich seeds.","The law defines rape as a serious crime.","The chronicle described the rape of the town."],"The farm harvested rape for its oil-rich seeds.","Oil-rich seeds and harvest identify the agricultural homograph.","confusable"),Q("rape.q4","rape.s2","word-choice","The court convicted the man after finding that he had ____ the victim.",["raped","raced","ranted"],"raped","The sentence requires the verb naming the serious crime the court found.","word-choice")]});
D("rapid",{etymology:E("From French rapide and Latin rapidus ‘hasty, swift; snatching’, from rapere ‘seize, carry off’; the speed sense developed from the image of something carried away quickly.",null,"rapere","-id","Etymonline, rapid (https://www.etymonline.com/word/rapid)."),contexts:[C("rapid.s1","醫學","The patient's rapid recovery surprised the care team, who had expected the infection to take several weeks to clear.","病人迅速康復，讓原本預期感染需數週才會消退的醫療團隊感到驚訝。","Rapid means happening in a short time or moving very fast.","Rapid modifies recovery; who introduces the team's expectation for comparison.","The recovery occurred much sooner than anticipated.") ,C("rapid.s2","運動","The cyclist made a rapid turn at the final marker and accelerated toward the finish line.","自行車手在最後一個標記處快速轉彎，接著加速衝向終點。","Rapid can describe an action performed with quick movement.","Rapid modifies turn; and then sequences the turn and acceleration.","The turn is executed at high speed.") ,C("rapid.s3","地理","Kayakers carried their boats around the rapids, where the river dropped over rocks in fast, churning water.","在河水高速翻騰、越過岩石下落的急流處，划艇者把船抬著繞行。","Rapids are sections of a river where water flows very fast over rocks.","Rapids is the object of around; where introduces the dangerous water conditions.","The plural noun names turbulent fast-flowing river sections.")],mistakes:[M("word-choice","The rapid recovery happened so slowly that the patient needed two years to regain strength.","The slow recovery took two years before the patient regained strength.","A two-year recovery is slow, not rapid.")],quiz:[Q("rapid.q1","rapid.s1","meaning","A rapid change happens ___.",["in a short time","only after many centuries","without any movement or change"],"in a short time","Rapid describes something happening quickly.","meaning"),Q("rapid.q2","rapid.s2","context","A rapid movement in fencing is a movement that is ___.",["done with quick action","measured over several years","chosen by a lottery"],"done with quick action","This use describes an action performed quickly.","context"),Q("rapid.q3","rapid.s3","meaning","A kayaker should be cautious near rapids because the river there ___.",["flows quickly over rocks","is dry and motionless","has been ranked by length"],"flows quickly over rocks","Rapids are fast, turbulent parts of a river.","meaning"),Q("rapid.q4","rapid.s1","word-choice","The alarm caused a ____ response from the rescue team.",["rapid","rancid","rancorous"],"rapid","The team responded quickly, so rapid fits.","word-choice")]});
D("rapidity",{etymology:E("Formed from rapid + -ity, from French rapidité and ultimately Latin rapidus ‘swift’; the noun names the quality of being very fast.",null,"rapid","-ity","Etymonline, rapid (https://www.etymonline.com/word/rapid)."),contexts:[C("rapidity.s1","科技","The rapidity of the data transfer increased after the lab replaced the damaged network cable.","實驗室更換受損的網路線後，資料傳輸速度加快了。","Rapidity is the quality or degree of being fast.","Rapidity is the subject; of the data transfer identifies what is fast, and after gives the cause.","The transfer now happens at a higher speed.")],mistakes:[M("meaning","The rapidity of the transfer was low because every file took three days to arrive.","The slowness of the transfer was high because every file took three days to arrive.","A process taking days has low rapidity; rapidity means speed or quickness.")],quiz:[Q("rapidity.q1","rapidity.s1","meaning","Rapidity refers to ___.",["speed or quickness","a strong lasting grudge","the quality of being rare"],"speed or quickness","Rapidity is the quality of being very fast.","meaning"),Q("rapidity.q2","rapidity.s1","context","Which event has greater rapidity?",["A file downloads in seconds rather than hours.","A file remains queued for a week.","A file is never sent."],"A file downloads in seconds rather than hours.","The shorter time indicates greater speed.","context"),Q("rapidity.q3","rapidity.s1","word-formation","Rapidity is the abstract noun related to which adjective?",["rapid","rampant","rapport"],"rapid","The suffix -ity forms a noun from rapid.","word-formation"),Q("rapidity.q4","rapidity.s1","word-choice","Researchers noted the ____ with which the signal crossed the short cable.",["rapidity","rareness","rancor"],"rapidity","The sentence refers to the signal's speed.","word-choice")]});
D("rapidly",{etymology:E("Formed from rapid + -ly, the regular adverb suffix; rapid comes through French from Latin rapidus ‘swift’, related to rapere ‘carry away, seize’.",null,"rapid","-ly","Etymonline, rapid (https://www.etymonline.com/word/rapid)."),contexts:[C("rapidly.s1","環境","The river rose rapidly after two days of heavy rain, forcing residents to leave the lowest streets.","連續兩天豪雨後，河水迅速上漲，迫使居民離開地勢最低的街道。","Rapidly means at a fast pace or within a short time.","Rapidly modifies rose; after introduces the cause, and forcing states the consequence.","The water level increased quickly enough to require evacuation.")],mistakes:[M("meaning","The seedlings grew rapidly, remaining the same height for ten months with no new leaves.","The seedlings barely grew, remaining the same height for ten months with no new leaves.","No measurable growth for ten months is not rapid growth.")],quiz:[Q("rapidly.q1","rapidly.s1","meaning","If a rumor spreads rapidly, it spreads ___.",["quickly","only once a year","in a carefully ranked list"],"quickly","Rapidly is the adverb meaning at a fast pace.","meaning"),Q("rapidly.q2","rapidly.s1","context","Which machine is working rapidly?",["It packages 500 boxes in an hour.","It takes a week to package one box.","It is switched off all day."],"It packages 500 boxes in an hour.","The machine processes many items in a short time.","context"),Q("rapidly.q3","rapidly.s1","word-form","Choose the adverb: “The population grew ___.”",["rapidly","rapid","rapidity"],"rapidly","Rapidly modifies the verb grew.","word form"),Q("rapidly.q4","rapidly.s1","word-choice","The color faded ____ in the direct afternoon sun.",["rapidly","rancorously","random"],"rapidly","The sentence describes how quickly the color faded.","word form")]});
D("rapport",{etymology:E("Borrowed from French rapport ‘relation, harmony’, back-formed from rapporter ‘bring back, refer to’, with re- ‘back/again’ and apporter, from Latin apportare ‘bring’ (ad- + portare ‘carry’).", "re-","portare",null,"Etymonline, rapport (https://www.etymonline.com/word/rapport)."),contexts:[C("rapport.s1","醫療","The counselor built rapport with the teenager by listening without judgment and remembering details from earlier sessions.","輔導員不帶批判地傾聽，並記得先前會談的細節，逐漸與青少年建立融洽關係。","Rapport is a friendly, trusting relationship in which people understand one another.","Built rapport is the verb-noun construction; with introduces the person, and by explains how it formed.","Careful listening helps the counselor and teenager communicate comfortably.")],mistakes:[M("meaning","The interviewer had strong rapport with the guest, but they distrusted one another and could not communicate at all.","The interviewer had little rapport with the guest because they distrusted one another and could not communicate comfortably.","Rapport means a harmonious, mutually understanding relationship, not distrust and failed communication.")],quiz:[Q("rapport.q1","rapport.s1","meaning","Good rapport between a teacher and student means ___.",["they communicate with mutual understanding","they have a large rank difference","they are selected at random"],"they communicate with mutual understanding","Rapport is a friendly connection that supports understanding.","meaning"),Q("rapport.q2","rapport.s1","context","Which action is most likely to build rapport with a new client?",["Listening carefully and responding to the client's concerns","Ignoring every answer","Correcting the client's name without asking"],"Listening carefully and responding to the client's concerns","Respectful listening helps create a comfortable relationship.","context"),Q("rapport.q3","rapport.s1","collocation","The interviewer quickly established ____ with the nervous witness.",["rapport","rapidity","rancidness"],"rapport","Establish rapport is a natural collocation for building understanding.","collocation"),Q("rapport.q4","rapport.s1","word-choice","The coach's calm questions helped create a sense of ____ among the players.",["rapport","ransom","rareness"],"rapport","A friendly connection among the players is rapport.","word-choice")]});
D("raptor",{etymology:E("From Latin raptor ‘robber, plunderer’, an agent noun from rapere ‘seize’; it first described a plundering bird and later became the ornithological term for a bird of prey.",null,"rapere","-or","Etymonline, raptor (https://www.etymonline.com/word/raptor)."),contexts:[C("raptor.s1","動物學","The wildlife team fitted a GPS tag to the raptor and released the hawk after checking its injured wing.","野生動物團隊替這隻猛禽裝上 GPS 標籤，檢查牠受傷的翅膀後便將牠放飛。","A raptor is a bird that hunts other animals, usually with a hooked beak and sharp talons.","Raptor is the object of fitted and released; after introduces the sequence of care.","The hawk is a predatory bird fitted with a tracking tag.")],mistakes:[M("meaning","The field guide classified the seed-eating sparrow as a raptor because it had a flat bill and no hunting talons.","The field guide classified the hawk as a raptor because it hunted with a hooked bill and sharp talons.","A raptor is a predatory bird with hunting adaptations; the described seed-eating sparrow does not fit.")],quiz:[Q("raptor.q1","raptor.s1","meaning","A raptor is a bird that typically ___.",["hunts other animals with a hooked beak and talons","feeds only on grass","lives underwater"],"hunts other animals with a hooked beak and talons","Raptors are birds of prey with grasping feet and hooked bills.","meaning"),Q("raptor.q2","raptor.s1","context","Which bird is a raptor?",["An eagle catching a fish with its talons","A duck filtering seeds from mud","A hummingbird drinking nectar"],"An eagle catching a fish with its talons","The eagle hunts prey using its talons.","context"),Q("raptor.q3","raptor.s1","word-choice","The injured ____ was taken to a wildlife center for treatment before release.",["raptor","rapport","rapidly"],"raptor","A bird of prey receiving care is a raptor.","word-choice"),Q("raptor.q4","raptor.s1","meaning","Why is an eagle called a raptor?",["It is a bird of prey that seizes animals.","It is a mammal that grazes on a ranch.","It is a fast-flowing part of a river."],"It is a bird of prey that seizes animals.","The word comes from a Latin term for a seizer or robber and names predatory birds.","meaning")]});
D("rapture",{etymology:E("From Middle French rapture and Latin raptura ‘a carrying off’, from rapere ‘seize, carry away’; the emotional sense is figurative, as if someone were carried beyond ordinary feeling.",null,"rapere","-ure","Etymonline, rapture (https://www.etymonline.com/word/rapture)."),contexts:[C("rapture.s1","音樂","The audience listened in rapture as the choir's final chord filled the old stone hall.","合唱團最後一個和弦迴盪在古老石廳時，聽眾聽得如痴如醉。","Rapture is a feeling of extreme happiness or delight.","In rapture describes the audience's state; as introduces the event that prompted it.","The music gives the audience an intense feeling of delight.") ,C("rapture.s2","藝術","She spoke about the painting with rapture, pointing out the golden light and the tiny figures in the distance.","她談起那幅畫時滿懷著迷，指出金色光線和遠處的小人物。","Rapture can mean deep delight or absorption in beauty, art, or music.","With rapture modifies spoke; pointing out gives examples of what holds her attention.","Her pleasure comes from close attention to the painting's beauty.") ,C("rapture.s3","文學","The news that the missing dog had been found raptured the children, who ran to meet it at the gate.","得知失蹤的狗找到了，孩子們欣喜若狂，跑到門口迎接牠。","As a verb, rapture means fill someone with great joy.","Raptured takes children as its object; who introduces their response.","The discovery makes the children extremely happy.")],mistakes:[M("meaning","The children watched the award ceremony in rapture, bored and eager for it to end.","The children watched the award ceremony without interest, bored and eager for it to end.","Rapture describes intense delight, which conflicts with boredom and eagerness to leave.")],quiz:[Q("rapture.q1","rapture.s1","meaning","To listen in rapture is to listen with ___.",["intense delight","deep resentment","no attention at all"],"intense delight","Rapture is an intense feeling of joy or happiness.","meaning"),Q("rapture.q2","rapture.s2","context","An art lover speaks about a sculpture with rapture. She is ___.",["deeply delighted and absorbed by it","angry about a ransom","checking its price rate"],"deeply delighted and absorbed by it","Rapture can describe deep delight in art or beauty.","context"),Q("rapture.q3","rapture.s3","grammar","In “The surprise raptured the children,” the verb means it ___.",["filled them with great joy","made them move rapidly","ranked them first"],"filled them with great joy","The verb sense means to fill a person with happiness.","meaning"),Q("rapture.q4","rapture.s1","word-choice","The singer's performance filled the crowd with ____.",["rapture","rancor","rareness"],"rapture","The crowd experiences overwhelming delight.","word-choice")]});
D("rare",{etymology:E("From Old French rere and directly from Latin rarus ‘thinly spaced, uncommon’; the cooking sense ‘not fully cooked’ developed in English, with the precise bridge to the older adjective uncertain.",null,"rarus",null,"Etymonline, rare (https://www.etymonline.com/word/rare)."),contexts:[C("rare.s1","收藏","A first edition of the atlas is rare, with only three verified copies held in public libraries.","這本地圖集初版十分罕見，目前只有三本經確認的複本收藏在公共圖書館。","Rare means not seen or found often.","Rare is the subject complement after is; with introduces evidence for its scarcity.","Only a few copies are known to exist.") ,C("rare.s2","地理","At the summit, the rare air made the climber breathe harder despite the cool temperature.","在山頂，稀薄的空氣讓登山者呼吸更加費力，儘管氣溫涼爽。","Rare can describe air that is thin and contains less oxygen than usual.","Rare modifies air; at the summit locates the high-altitude condition.","The thinner high-altitude air provides less oxygen per breath.") ,C("rare.s3","餐飲","The diner ordered a rare steak, seared on the outside but still red at the center.","顧客點了一份三分熟牛排，外面煎熟，中心仍帶紅色。","Rare describes meat cooked briefly so the center remains red.","Rare modifies steak; the participial phrase specifies the cooking result.","The meat is lightly cooked rather than fully done.")],mistakes:[M("meaning","The rare manuscript was an ordinary mass-produced booklet printed in ten million identical copies.","The common manuscript was an ordinary mass-produced booklet printed in ten million identical copies.","An item produced in millions of identical copies is not uncommon or rare.")],quiz:[Q("rare.q1","rare.s1","meaning","A rare coin is ___.",["uncommon and difficult to find","one of millions in everyday use","a fast-moving river"],"uncommon and difficult to find","Rare means not found often.","meaning"),Q("rare.q2","rare.s2","context","A climber notices rare air near a high summit. The air is ___.",["thin and low in oxygen","thick with extra oxygen","warm enough to melt rock"],"thin and low in oxygen","At high altitude, rare air is less dense.","context"),Q("rare.q3","rare.s3","context","A steak ordered rare should have a center that is ___.",["red and lightly cooked","cooked until dry throughout","frozen solid"],"red and lightly cooked","Rare meat is cooked briefly and remains red in the middle.","context"),Q("rare.q4","rare.s1","word-choice","The museum displayed a ____ map that had survived from the 1500s.",["rare","rancid","rank"],"rare","A map from the 1500s with few surviving copies is uncommon.","word-choice")]});
D("rarefy",{etymology:E("From Old French rarefier and Latin rarefacere ‘make thin or less dense’, combining rarus ‘thin, uncommon’ with facere ‘make’; figuratively it can also make an idea more refined or abstract.",null,"rarus + facere","-fy","Etymonline, rarefy (https://www.etymonline.com/word/rarefy)."),contexts:[C("rarefy.s1","物理","Heating the sealed gas caused it to rarefy and expand, lowering the number of molecules in each litre.","加熱密封氣體使其變得稀薄並膨脹，降低每公升所含的分子數。","To rarefy is to make a gas less dense; figuratively it can refine an idea until it becomes abstract.","Rarefy takes gas as its object; and links its expansion to the resulting decrease in density.","The gas occupies more volume, so its particles are less concentrated.")],mistakes:[M("meaning","The engineer rarefied the gas by compressing it into half its original volume and increasing its density.","The engineer compressed the gas into half its original volume and increased its density.","Compressing a gas increases density; rarefy means make it less dense.")],quiz:[Q("rarefy.q1","rarefy.s1","meaning","To rarefy a gas is to ___.",["make it less dense","make it more concentrated","turn it into a solid by pressure"],"make it less dense","Rarefy means reduce the density of a gas.","meaning"),Q("rarefy.q2","rarefy.s1","context","Why might heated air in a room rarefy?",["It expands and becomes less dense.","It is squeezed into a smaller space.","It turns into liquid water immediately."],"It expands and becomes less dense.","Expansion spreads the gas particles through a larger volume.","context"),Q("rarefy.q3","rarefy.s1","word-formation","The Latin source rarefacere combined rarus with a verb meaning ___.",["make","seize","carry"],"make","Facere means ‘make’; the compound meant make thin or less dense.","word-formation"),Q("rarefy.q4","rarefy.s1","word-choice","A scientist used heat to ____ the gas in the chamber.",["rarefy","ransack","ransom"],"rarefy","The scientist made the gas less dense by heating it.","word-choice")]});
D("rarely",{etymology:E("Formed from rare + -ly, the regular adverb suffix; rare comes from Latin rarus ‘thinly spaced, uncommon’. Rarely means not often.",null,"rarus","-ly","Etymonline, rare (https://www.etymonline.com/word/rare)."),contexts:[C("rarely.s1","生活","The mountain pass is rarely open in winter because snow blocks the road for weeks at a time.","這座山口冬天很少開放，因為大雪常常封路好幾週。","Rarely means not often or only on few occasions.","Rarely modifies is open; because supplies the reason for the infrequent opening.","Winter closures make access an uncommon event.")],mistakes:[M("meaning","She rarely misses a rehearsal, arriving late almost every day of the week.","She often misses a rehearsal, arriving late almost every day of the week.","Missing almost every day describes frequent behavior, not something that happens rarely.")],quiz:[Q("rarely.q1","rarely.s1","meaning","If a shop rarely closes early, it closes early ___.",["not often","every day","at every opportunity"],"not often","Rarely means on few occasions.","meaning"),Q("rarely.q2","rarely.s1","context","Which sentence uses rarely correctly?",["The ferry rarely runs in winter because the harbor freezes.","The ferry rarely runs every hour without interruption.","The ferry rarely is common and daily."],"The ferry rarely runs in winter because the harbor freezes.","A frozen harbor explains why ferry service is infrequent.","context"),Q("rarely.q3","rarely.s1","word-form","Choose the adverb: “They ___ eat out during the workweek.”",["rarely","rare","rarity"],"rarely","Rarely modifies the verb eat and means not often.","word form"),Q("rarely.q4","rarely.s1","word-choice","Because the archive is open only twice a year, visitors can enter it ____.",["rarely","rapidly","rancorously"],"rarely","Two openings per year make visits infrequent.","word form")]});
D("rareness",{etymology:E("Formed from rare + -ness, the state or quality suffix; it names uncommon occurrence and, in cooking, the degree to which meat remains lightly cooked.",null,"rare","-ness","Etymonline, rare (https://www.etymonline.com/word/rare)."),contexts:[C("rareness.s1","餐飲","The chef checked the rareness of the roast at its center before serving it to guests who had requested pink meat.","主廚上菜前檢查烤肉中心的熟度，因為客人特別要求肉呈粉紅色。","Rareness is the state of being uncommon or, of meat, the degree to which it remains red or lightly cooked.","Rareness is the object of checked; at its center locates the test and before gives the sequence.","The chef checks whether the center is cooked to the requested rare degree.")],mistakes:[M("meaning","The rareness of the roast meant it had been cooked until no pink remained and the center was completely well done.","The doneness of the roast meant it had been cooked until no pink remained and the center was completely well done.","Rareness of meat refers to light cooking with a red or pink center, not well-done meat.")],quiz:[Q("rareness.q1","rareness.s1","meaning","The rareness of a surviving manuscript refers to its ___.",["scarcity","speed","price per hour"],"scarcity","Rareness is the state of being uncommon.","meaning"),Q("rareness.q2","rareness.s1","context","A chef checks a steak's rareness. What is being checked?",["How lightly cooked and red the center remains","Whether the steak was selected at random","How quickly the steak cooled"],"How lightly cooked and red the center remains","In cooking, rareness describes how rare or lightly cooked the meat is.","context"),Q("rareness.q3","rareness.s1","word-formation","Which suffix forms rareness from rare?",["-ness","-ly","-er"],"-ness","The suffix -ness forms a noun naming a state or quality.","word-formation"),Q("rareness.q4","rareness.s1","word-choice","The collector admired the ____ of a book with only one known copy.",["rareness","rapidity","rashness"],"rareness","One known copy makes the book exceptionally uncommon.","word-choice")]});
D("rarity",{etymology:E("From Old French rareté and Latin raritatem, from rarus ‘thinly spaced, uncommon’; the noun names scarcity and can also name an unusually valuable object.",null,"rarus","-ity","Etymonline, rare (https://www.etymonline.com/word/rare)."),contexts:[C("rarity.s1","生態","The rarity of the snow leopard made the camera-trap images especially important to conservation researchers.","雪豹十分稀有，因此相機陷阱拍到的影像對保育研究人員格外重要。","Rarity is the state of being uncommon or present in small numbers.","Rarity is the subject; of the snow leopard identifies the scarce species.","Few sightings make each reliable image valuable to research.") ,C("rarity.s2","收藏","The signed first printing is a rarity among local bookshops, and collectors travel to see it.","這本簽名初版在當地書店中是珍品，收藏家專程前來一睹。","A rarity can be an unusual and valuable thing because it is scarce.","Rarity is the complement after is; among local bookshops gives the comparison set.","The copy is prized because few others are available.") ,C("rarity.s3","地理","The rarity of air at the high observatory required researchers to acclimatize before beginning long shifts.","高海拔天文台的空氣稀薄，因此研究人員必須先適應，才能開始長時間輪班。","Rarity can also refer to the thinness of air at high altitude.","Rarity is the subject; of air identifies what is thin, and at the observatory sets the location.","The high elevation means fewer air molecules per volume.")],mistakes:[M("meaning","The rarity of the common pebble was obvious because every beach and garden contained millions of identical stones.","The abundance of the common pebble was obvious because every beach and garden contained millions of identical stones.","An object found in millions of places is abundant rather than rare.")],quiz:[Q("rarity.q1","rarity.s1","meaning","The rarity of a species means the species is ___.",["scarce or found in small numbers","found everywhere in huge numbers","a machine that advances in steps"],"scarce or found in small numbers","Rarity describes uncommon occurrence.","meaning"),Q("rarity.q2","rarity.s2","context","A signed manuscript is described as a rarity. This means it is ___.",["an unusual and valuable item","a routine mass-produced copy","a rapid river current"],"an unusual and valuable item","A rarity can be a scarce object prized for its unusualness.","context"),Q("rarity.q3","rarity.s3","meaning","At high altitude, rarity of the air refers to ___.",["low density of the air","a large number of air molecules","the air's pleasant smell"],"low density of the air","The high-altitude sense refers to thin, less dense air.","meaning"),Q("rarity.q4","rarity.s1","word-choice","The ____ of wild orchids in the valley led botanists to protect their habitat.",["rarity","rapacity","rapidity"],"rarity","A scarce species' occurrence is its rarity.","word-choice")]});
D("rascal",{etymology:E("From Old French rascaille ‘rabble, mob’, later applied to a dishonest or mischievous person; the deeper origin of the French form is uncertain.",null,"rascaille",null,"Etymonline, rascal (https://www.etymonline.com/word/rascal)."),contexts:[C("rascal.s1","日常","The little rascal hid his sister's mittens as a joke, then returned them when she began to worry.","這個小淘氣把妹妹的手套藏起來開玩笑，見她開始擔心後才還給她。","A rascal is a dishonest or mischievous person, sometimes said affectionately.","Rascal is the subject complement after little; the two clauses show the prank and its resolution.","The child behaves mischievously but not maliciously.")],mistakes:[M("meaning","Everyone called the rascal honest because he returned every wallet he found and never played a trick.","Everyone called the good-natured boy honest because he returned every wallet he found and never played a trick.","A rascal is dishonest or mischievous; the described behavior is consistently honest and helpful.")],quiz:[Q("rascal.q1","rascal.s1","meaning","A good-natured rascal is often ___.",["mischievous but amusing","a formal ranking list","a spoiled cooking oil"],"mischievous but amusing","Rascal can be a playful term for someone who causes harmless trouble.","meaning"),Q("rascal.q2","rascal.s1","context","Which child might a parent affectionately call a rascal?",["One who hides a hat as a joke and gives it back","One who quietly reads a book","One who repairs a broken gate"],"One who hides a hat as a joke and gives it back","The harmless prank is mischievous behavior.","context"),Q("rascal.q3","rascal.s1","register","Calling a close friend a rascal may sound ___.",["teasing or affectionate","strictly scientific","like a legal verdict"],"teasing or affectionate","The word can be playful when used for a mischievous person.","register"),Q("rascal.q4","rascal.s1","word-choice","The young ____ swapped the coach's whistle for a toy one, then confessed.",["rascal","raptor","rater"],"rascal","The prankster is a mischievous person.","word-choice")]});
D("rash",{etymology:E("The adjective's deeper origin is uncertain; English used it for hasty or impetuous action by the 14th century. The skin eruption and the series-of-events noun senses developed as separate uses of the same form.",null,null,null,"Etymonline, rash (https://www.etymonline.com/word/rash)."),contexts:[C("rash.s1","決策","It was rash to sign the lease before checking the building for water damage and reading the cancellation terms.","尚未檢查建築是否漏水、也未讀取消約條款就簽租約，實在太輕率。","Rash describes acting too quickly without considering likely consequences.","Rash follows was as a subject complement; to sign names the action judged, and before states what was skipped.","The tenant commits without checking important risks.") ,C("rash.s2","醫學","A red rash appeared on the child's arms after the new detergent was used on the bedding.","使用新洗衣精清洗床單後，孩子手臂上出現紅疹。","A rash is an area of small red spots on the skin.","Rash is the subject; after introduces the event that preceded its appearance.","The skin spots may be a reaction to the detergent.") ,C("rash.s3","新聞","Police investigated a rash of bicycle thefts after twelve bikes disappeared from the station in one week.","一週內車站有十二輛自行車失竊後，警方開始調查這一連串竊案。","A rash can mean a sudden series of unpleasant events.","Rash of thefts is a noun phrase; after introduces the evidence behind the investigation.","The many thefts occurred close together in time.")],mistakes:[M("meaning","Her rash decision followed months of research, a safety review, and careful comparison of every option.","Her considered decision followed months of research, a safety review, and careful comparison of every option.","A rash decision is made without enough thought; the listed careful steps contradict that description.")],quiz:[Q("rash.q1","rash.s1","meaning","A rash decision is one made ___.",["too quickly and without considering the results","after careful review of every risk","by a random number generator"],"too quickly and without considering the results","The adjective describes reckless, insufficiently considered action.","meaning"),Q("rash.q2","rash.s2","context","A doctor examines a rash on a patient's arm. The doctor examines ___.",["small red spots on the skin","a military rank","a rapid river"],"small red spots on the skin","The noun rash names a skin eruption.","context"),Q("rash.q3","rash.s3","meaning","A rash of break-ins means ___.",["a sudden series of break-ins","one carefully planned break-in","a red mark on a door"],"a sudden series of break-ins","This noun sense describes many unpleasant events occurring close together.","meaning"),Q("rash.q4","rash.s1","word-choice","Ignoring the warning and driving into the flooded road was a ____ choice.",["rash","rare","rancid"],"rash","The driver acted recklessly without weighing the danger.","word-choice")]});
D("rashly",{etymology:E("Formed from rash + -ly; rash is the adjective for acting hastily or without weighing consequences, and -ly forms the manner adverb.",null,"rash","-ly","Etymonline, rash (https://www.etymonline.com/word/rash)."),contexts:[C("rashly.s1","決策","The treasurer rashly promised to cover the entire cost before checking the club's remaining funds.","財務在查清社團剩餘資金前，就輕率承諾承擔全部費用。","Rashly means acting without enough thought or consideration.","Rashly modifies promised; before marks the financial check that should have come first.","The treasurer commits before knowing whether the club can afford it.") ,C("rashly.s2","安全","The climber rashly crossed the icy ledge without a rope, ignoring the guide's warning about the drop.","登山者不顧嚮導對落差的警告，魯莽地在沒有繩索的情況下越過結冰山脊。","Rashly can mean acting in a way that ignores danger or cost.","Rashly modifies crossed; without and ignoring identify the precautions and warning disregarded.","The climber takes a known physical risk without protection.")],mistakes:[M("meaning","She rashly waited for a weather report, consulted the guide, and checked all safety equipment before deciding.","She cautiously waited for a weather report, consulted the guide, and checked all safety equipment before deciding.","These careful precautions show caution, not rash action without consideration.")],quiz:[Q("rashly.q1","rashly.s1","meaning","To act rashly is to act ___.",["without thinking enough first","after checking all relevant facts","according to a carefully tested plan"],"without thinking enough first","Rashly describes a hurried, insufficiently considered act.","meaning"),Q("rashly.q2","rashly.s2","context","Which action was done rashly?",["Crossing a dangerous ledge without a rope despite a warning","Waiting for safe weather and using a harness","Asking a guide to inspect the route"],"Crossing a dangerous ledge without a rope despite a warning","Ignoring a known hazard is reckless.","context"),Q("rashly.q3","rashly.s1","word-form","Choose the adverb: “He ___ accepted the offer without reading it.”",["rashly","rash","rashness"],"rashly","The adverb rashly modifies accepted.","word form"),Q("rashly.q4","rashly.s2","confusable","Which word best contrasts with rashly in a safety decision?",["cautiously","randomly","rapidly"],"cautiously","Careful attention to danger contrasts with reckless action.","confusable")]});
D("rashness",{etymology:E("Formed from rash + -ness, a suffix making a state or quality noun; rash is the adjective describing insufficiently considered action.",null,"rash","-ness","Etymonline, rash (https://www.etymonline.com/word/rash)."),contexts:[C("rashness.s1","職場","The board regretted its rashness in announcing layoffs before confirming the company's cash forecast.","董事會後悔在確認公司現金預測前就宣布裁員的輕率行為。","Rashness is the quality of acting without thinking enough about the results.","Rashness is the object of regretted; in announcing identifies the action that was premature.","The board acted before confirming financial facts that mattered.")],mistakes:[M("meaning","The report praised the manager's rashness because she reviewed every risk and waited for verified figures.","The report praised the manager's caution because she reviewed every risk and waited for verified figures.","Reviewing risks and waiting for facts demonstrate caution, not rashness.")],quiz:[Q("rashness.q1","rashness.s1","meaning","Rashness is ___.",["the quality of acting without enough thought","a harmless skin irritation","a close friendly relationship"],"the quality of acting without enough thought","Rashness names the trait of making reckless decisions.","meaning"),Q("rashness.q2","rashness.s1","context","Why did the board regret its rashness?",["It announced layoffs before checking the cash forecast.","It waited for verified figures before acting.","It asked auditors to review the plan."],"It announced layoffs before checking the cash forecast.","The premature announcement shows inadequate consideration.","context"),Q("rashness.q3","rashness.s1","word-formation","What does -ness form in rashness?",["a noun naming a quality or state","an adverb of manner","a person who acts"],"a noun naming a quality or state","The suffix -ness forms an abstract quality noun.","word-formation"),Q("rashness.q4","rashness.s1","word-choice","The pilot's ____ in ignoring the warning put the crew at risk.",["rashness","rapidity","rarity"],"rashness","The pilot acted without considering the warning's consequences.","word-choice")]});
D("rat",{etymology:E("The rodent noun is Old English ræt, of uncertain deeper origin. The informal trait ‘disloyal person/informant’ developed later from the idea of a rat abandoning a sinking ship; the verb rat on means betray or inform on someone.",null,null,null,"Etymonline, rat (https://www.etymonline.com/word/rat)."),contexts:[C("rat.s1","生物","A brown rat squeezed through the drain opening and nibbled the grain stored in the basement.","一隻褐家鼠鑽過排水口，啃食存放在地下室的穀物。","A rat is a rodent resembling a large mouse, with a long tail.","Rat is the subject; through introduces its route, while and links its two actions.","The animal enters the basement and feeds on stored grain.") ,C("rat.s2","口語","After he secretly gave the team list to their rivals, the players called him a rat.","他偷偷把隊伍名單交給對手後，隊員們罵他是叛徒。","Informally, a rat is a disloyal or unpleasant person.","Rat follows called him as the object complement; after introduces the betrayal.","The insult criticizes his disloyalty to his own team.") ,C("rat.s3","口語","One accomplice ratted on the others and gave police the address of the hidden equipment.","一名共犯向警方告發其他人，並提供藏匿設備的地址。","To rat on someone is to betray them or inform the police about them.","Ratted is followed by on and the people betrayed; and links the report's two details.","The accomplice supplies information to law enforcement about associates.")],mistakes:[M("collocation","The accomplice ratted the others to the police by giving their address.","The accomplice ratted on the others to the police by giving their address.","The betrayal sense uses rat on someone; on should precede the person reported.")],quiz:[Q("rat.q1","rat.s1","meaning","A rat in a basement is ___.",["a long-tailed rodent","a military ranking","a rare cooking style"],"a long-tailed rodent","The animal sense refers to a rodent larger than a mouse.","meaning"),Q("rat.q2","rat.s2","register","Calling a teammate a rat usually accuses the person of being ___.",["disloyal","a rodent in a literal sense only","careful and trustworthy"],"disloyal","The informal person sense means traitor or unpleasant betrayer.","register"),Q("rat.q3","rat.s3","collocation","Complete: “He ratted ___ his accomplices to the police.”",["on","at","for"],"on","The phrasal verb is rat on someone.","collocation"),Q("rat.q4","rat.s3","context","A person “ratted on” a criminal group by giving police its location. The person ___.",["informed on the group","fed a pet rat","ranked the group"],"informed on the group","Rat on means betray or give information about someone to police.","context")]});
D("ratchet",{etymology:E("From French rochet for a notched wheel, with the modern English spelling influenced by ratch and perhaps German Rätsche ‘ratchet’; the mechanism's teeth allow movement one way while preventing it from slipping back.",null,"rochet / Rätsche",null,"Etymonline, ratchet (https://www.etymonline.com/word/ratchet)."),contexts:[C("ratchet.s1","工程","The mechanic tightened the bolt with a ratchet, turning the handle clockwise while the socket stayed on the nut.","技工用棘輪扳手鎖緊螺栓，順時針轉動手柄時套筒仍卡在螺帽上。","A ratchet is a toothed mechanism that permits step-by-step motion while resisting movement backward.","With a ratchet introduces the tool; while links turning the handle to the socket's position.","The mechanism lets the handle reset without loosening the bolt.")],mistakes:[M("meaning","The ratchet let the bolt unwind freely in both directions with no catch or teeth to stop reverse motion.","The ratchet let the bolt turn step by step while its catch prevented reverse motion.","A ratchet's catch and teeth resist backward movement rather than allowing free reversal.")],quiz:[Q("ratchet.q1","ratchet.s1","meaning","A ratchet mechanism allows motion ___.",["in steps while resisting backward movement","only in a smooth circle with no stops","at random in every direction"],"in steps while resisting backward movement","A catch engages teeth to prevent slipping back.","meaning"),Q("ratchet.q2","ratchet.s1","context","Why use a ratchet wrench in a tight space?",["The handle can reset without removing the socket from the bolt.","It turns bolts only by heating them.","It changes the bolt's rank."],"The handle can reset without removing the socket from the bolt.","Step-by-step movement is useful when the handle cannot make a full turn.","context"),Q("ratchet.q3","ratchet.s1","word-choice","The mechanic used a ____ to turn the nut a few clicks at a time.",["ratchet","rancor","raptor"],"ratchet","A ratchet advances a fastener in small steps.","word-choice"),Q("ratchet.q4","ratchet.s1","meaning","What part stops a ratchet from slipping backward?",["A catch engaging the teeth","A smooth wax coating","A random number"],"A catch engaging the teeth","The pawl or catch holds the toothed wheel between steps.","meaning")]});
D("rate",{etymology:E("The noun came from Old French rate and Medieval Latin rata (pars) ‘fixed amount’, from Latin rata ‘fixed, settled’, the feminine participle of reri ‘reckon’. The verb meaning ‘judge or value’ developed from the noun; an older ‘scold’ verb has a separate route.",null,"reri / rata",null,"Etymonline, rate (https://www.etymonline.com/word/rate)."),contexts:[C("rate.s1","交通","The car's rate of speed fell sharply as it climbed the steep road in heavy snow.","汽車在大雪中爬上陡坡時，行進速度大幅下降。","Rate can mean the speed at which something happens or moves.","Rate is the subject; of speed identifies the measure, and as introduces the changing condition.","The car travels more slowly as road conditions worsen.") ,C("rate.s2","科學","The reaction rate doubled when the laboratory raised the temperature by ten degrees.","實驗室把溫度提高十度後，反應速率增加了一倍。","A rate can be a quantity measured against another quantity, such as events per unit of time.","Rate is the subject; when introduces the condition that changed it.","The reaction now occurs twice as often over the same time span.") ,C("rate.s3","金融","The hotel quoted a lower nightly rate for guests who booked a full week.","飯店為預訂整整一週的旅客提供較低的每晚費率。","A rate can be a fixed price or charge for a service.","Rate is the object of quoted; for introduces the eligible guests.","The price charged per night is lower for a week-long booking.") ,C("rate.s4","評比","Readers rated the new play highly for its original dialogue and carefully designed set.","讀者因新戲劇的原創對白與精心設計的布景而給予高度評價。","As a verb, rate means judge quality or assign a score.","Rated takes play as object; highly states the judgment and for gives the reasons.","Readers evaluate the play's quality and respond favorably.") ,C("rate.s5","評價","The short documentary rates a second viewing because its final interview changes the meaning of the opening scene.","這部短紀錄片值得再看一次，因為最後的訪談改變了開場場景的意義。","To rate can mean deserve a particular reaction or be considered worthy of it.","Rates takes viewing as its object; because gives the reason it deserves another viewing.","The work rewards another viewing with newly understood meaning.")],mistakes:[M("grammar","The short documentary rate a second viewing because its final interview changes the opening scene.","The short documentary rates a second viewing because its final interview changes the opening scene.","A singular subject takes rates in the present tense; the sentence uses rate as ‘deserves’.")],quiz:[Q("rate.q1","rate.s1","meaning","A heart rate measures ___.",["how often the heart beats over time","the price of a hospital room","a judge's opinion of a patient"],"how often the heart beats over time","Rate can be a speed or frequency per unit time.","meaning"),Q("rate.q2","rate.s2","context","If a factory's defect rate is 3 per 100 units, the rate compares ___.",["defects with units produced","the factory's height with its age","two unrelated prices"],"defects with units produced","A rate measures one quantity relative to another.","context"),Q("rate.q3","rate.s3","meaning","A room rate is the ___.",["price charged for the room","room's ranking among buildings","speed at which a door opens"],"price charged for the room","Rate can mean a fixed price or service charge.","meaning"),Q("rate.q4","rate.s5","word-choice","The thoughtful review said the film ____ a second viewing.",["rates","raps","ranches"],"rates","Here rates means deserves or is worth another viewing.","word-choice")]});
D("rater",{etymology:E("Formed from rate + -er, naming a person who gives an evaluation or rating; rate as a noun came through Old French from Medieval Latin rata ‘fixed amount’.",null,"rate","-er","Etymonline, rate (https://www.etymonline.com/word/rate)."),contexts:[C("rater.s1","教育","Each rater scored the essays independently before the teachers compared their results for consistency.","每位評分人先獨立替作文打分，教師之後再比較結果以確認一致性。","A rater is someone who judges quality, risk, or value and assigns a rating.","Rater is the subject; scored states the task, and before establishes that scoring preceded comparison.","The person evaluates each essay and assigns a score.")],mistakes:[M("meaning","The rater compared every essay but never assigned a score or rating to any of them.","The rater compared every essay and assigned each one a score.","A rater evaluates submissions and assigns ratings; comparison without any score does not complete that role.")],quiz:[Q("rater.q1","rater.s1","meaning","A rater is a person who ___.",["judges something and assigns a score or rating","raises cattle on open land","is held for ransom"],"judges something and assigns a score or rating","The noun names a person who evaluates quality or value.","meaning"),Q("rater.q2","rater.s1","context","In a risk review, the rater ___.",["assesses the risk and gives it a rating","repairs the machine without evaluating it","selects the machine at random"],"assesses the risk and gives it a rating","The rater evaluates risk and records a judgment.","context"),Q("rater.q3","rater.s1","word-formation","Rater is formed from which verb?",["rate","rave","rap"],"rate","Adding -er to rate forms a person noun.","word-formation"),Q("rater.q4","rater.s1","word-choice","The second ____ used the same rubric to score the applications.",["rater","ratchet","rancor"],"rater","A person assigning scores with a rubric is a rater.","word-choice")]});
})();

